```c
/* 直接写 USART0 寄存器输出，绕过 NuttX 串口协议栈 */
static void fireye_raw_putc(char ch)
{
  uintptr_t base = GD32_USART0_BASE;
  uint32_t ctl0;

  /* 确保发送使能（只置 TEN 位，不动其它配置） */
  ctl0 = getreg32(base + GD32_USART_CTL0_OFFSET);
  if ((ctl0 & USART_CTL0_TEN) == 0)
    {
      putreg32(ctl0 | USART_CTL0_TEN, base + GD32_USART_CTL0_OFFSET);
    }

  while ((getreg32(base + GD32_USART_STAT0_OFFSET) & USART_STAT0_TBE) == 0);
  putreg32((uint32_t)(uint8_t)ch, base + GD32_USART_DATA_OFFSET);
}

static void fireye_raw_puts(const char *s)
{
  while (*s) fireye_raw_putc(*s++);
}
