  /* 1) 打开 ADC0 时钟 */
  reg_write(RCU_APB2EN, reg_read(RCU_APB2EN) | RCU_APB2EN_ADC0EN);

  /* 2) ADC 时钟 = PCLK2/4（PCLK2=84MHz -> 21MHz，低于手册 40MHz 上限） */
  v = reg_read(GD32_ADC_SYNCCTL);
  v &= ~(7u << 16);
  v |= (1u << 16);
  reg_write(GD32_ADC_SYNCCTL, v);

  /* 3) PA4/PA6 配成模拟输入 */
  gd32_gpio_config(GPIO_CFG_MODE_ANALOG | GPIO_CFG_PUPD_NONE | GPIO_CFG_PORT_A | GPIO_CFG_PIN_4);
  gd32_gpio_config(GPIO_CFG_MODE_ANALOG | GPIO_CFG_PUPD_NONE | GPIO_CFG_PORT_A | GPIO_CFG_PIN_6);

  /* 4) 12 位分辨率、非扫描、单次转换 */
  reg_write(GD32_ADC_CTL0, ADC_CTL0_DRES_12BIT);
  reg_write(GD32_ADC_CTL1, 0);

  /* 5) 上电 */
  reg_write(GD32_ADC_CTL1, reg_read(GD32_ADC_CTL1) | ADC_CTL1_ADCON);
  usleep(2000);   /* 手册要求上电后等 tSU，这里给 2ms 足够 */

  /* 6) 校准 */
  reg_write(GD32_ADC_CTL1, reg_read(...) | ADC_CTL1_RSTCLB);
  while (reg_read(...) & ADC_CTL1_RSTCLB) ;      /* 硬件清零 */
  reg_write(..., | ADC_CTL1_CLB);
  while (reg_read(...) & ADC_CTL1_CLB) ;
