```c
int gd32_fireeye_adc_sample(int channel)
{
  uint32_t sampt, shift;
  int timeout;

  if (channel < 0 || channel > 18) return -EINVAL;

  /* 采样时间：选 480 周期（111），分压源阻抗约 5kΩ，留足充电时间 */
  if (channel < 10) { sampt = GD32_ADC_SAMPT1; shift = 3*channel; }
  else              { sampt = GD32_ADC_SAMPT0; shift = 3*(channel-10); }
  v = reg_read(sampt); v &= ~(7u<<shift); v |= (7u<<shift); reg_write(sampt, v);

  /* 单次转换：RL=0，序列第 1 个通道 = channel */
  v = reg_read(GD32_ADC_RSQ0); v &= ~(0xFu<<20); reg_write(RSQ0, v);   /* RL = 0 -> 1 次转换 */
  v = reg_read(GD32_ADC_RSQ2); v &= ~0x1Fu; v |= channel; reg_write(RSQ2, v);

  /* 清标志，启动 */
  reg_write(GD32_ADC_STAT, 0);   /* STAT 的 EOC/STRC 是 rc_w0 → 写 0 清除 */
  reg_write(GD32_ADC_CTL1, reg_read(CTL1) | ADC_CTL1_SWRCST);

  for (timeout = 0; timeout < 100000; timeout++)
    if (reg_read(GD32_ADC_STAT) & ADC_STAT_EOC) break;
  if (!(EOC)) return -ETIMEDOUT;

  return (int)(reg_read(GD32_ADC_RDATA) & 0xFFFF);
}
```
