Temperature:
```c
float fireeye_sensors_read_temperature(void)
{
  int raw = adc_read_avg(NTC_ADC_CH);
  if (raw < 0) return NAN;
  float v = raw * ADC_VREF / ADC_FULLSCALE;
  if (v <= 0.01f || v >= (ADC_VREF - 0.01f)) return NAN;   /* 开路/短路 */
  float r = NTC_R_SERIES * v / (ADC_VREF - v);
  float t = 1.0f / (1.0f/NTC_T0 + logf(r/NTC_R0)/NTC_B) - 273.15f;
  return t;
}
```

